import path from "path"
import fs from "fs"

const banner = `// Do not edit!
// This file is auto-generated by auto-export plugin (see vite.config.js)
`

let resolvePath = null
let writeFile = null
let isProd = true

export function setAutoExportHelpers(pathResolver, fileWriter, viteIsProd) {
  resolvePath = pathResolver
  writeFile = fileWriter
  isProd = viteIsProd
}

function getGenFilePath(name) {
  const fileName = name + ".js"
  return [fileName, resolvePath(fileName)]
}

const toPosix = pth => pth.replace(/\\/g, "/")

function toRelative(fileAbs) {
  const fromDirAbs = resolvePath()
  let rel = toPosix(path.relative(fromDirAbs, fileAbs))
  if (!rel.startsWith(".")) rel = "./" + rel
  return rel
}

function invalidateModuleByFile(server, filePath) {
  if (!server || !filePath) return
  const mods = server.moduleGraph.getModulesByFile(filePath)
  if (!mods) return
  for (const mod of mods) {
    server.moduleGraph.invalidateModule(mod)
  }
}

const watcherRouters = new WeakMap()
function ensureWatcherRouter(server) {
  if (watcherRouters.has(server)) return watcherRouters.get(server)

  const listeners = new Set()
  const dispatch = (event, file) => {
    const normalizedFile = toPosix(file || "")
    for (const listener of listeners) {
      listener(event, normalizedFile)
    }
  }

  server.watcher.on("add", file => dispatch("add", file))
  server.watcher.on("unlink", file => dispatch("unlink", file))

  const router = {
    subscribe(listener) {
      listeners.add(listener)
      return () => listeners.delete(listener)
    },
  }
  watcherRouters.set(server, router)
  return router
}

/**
 * Plugin to automatically export components, directives, etc
 * @param {string} name - Name of the exported module
 * @param {string} srcDir - Source directory to scan files in
 * @param {RegExp} pattern - Pattern to match for validation and replacement. Note: if pattern is not for vue files, specify multiple file extensions that include vue for demos to work.
 * @param {string|function} replace - Replacement for the file name
 * @returns {object} - Plugin thing
 */
export function autoExport(name, srcDir, pattern, replace) {
  const srcPath = path.resolve(__dirname, "src", srcDir)
  const srcPathPosix = toPosix(srcPath)

  const [outFileName, outFilePath] = getGenFilePath(name)
  let serverRef = null

  const generate = () => {
    const src = [banner]
    const names = []

    // sources
    fs.readdirSync(srcPath)
      .forEach(file => {
        let name = file
        if (name === outFileName) return
        if (name.includes(".dev.")) {
          if (isProd) return
          name = name.replace(".dev.", ".")
        }
        if (!pattern.test(name)) return
        name = name.replace(pattern, replace)
        names.push(name)
        const spec = toRelative(path.resolve(srcPath, file))
        src.push(`export { default as ${name} } from "${spec}"`)
      })

    // demos
    src.push("", "export const DEMOS = (import.meta.hot && import.meta.env.MODE !== \"test\") ? {")
    const demosDir = path.resolve(srcPath, "demos")
    fs.readdirSync(demosDir)
      .filter(f => f.endsWith(".vue")) // demos are always .vue
      .forEach(file => {
        let name = file
        if (!name.includes("_demo.")) return
        name = name.replace("_demo.", ".")
        if (!pattern.test(name)) return
        name = name.replace(pattern, replace)
        if (!names.includes(name)) {
          console.warn(`Found demo for non-existent component ${name}`)
          return
        }
        const spec = toRelative(path.resolve(demosDir, file))
        src.push(`  ${name}: import("${spec}"),`)
      })
    src.push("} : {}", "")

    // export
    const next = src.join("\n")
    const prev = fs.existsSync(outFilePath) ? fs.readFileSync(outFilePath, "utf8") : ""
    if (next !== prev) {
      writeFile(outFilePath, next)
      return true
    }
    return false
  }

  const regenerate = (forceReload = false) => {
    const changed = generate()
    if (!serverRef) return changed
    if (changed || forceReload) {
      invalidateModuleByFile(serverRef, outFilePath)
    }
    if (forceReload) {
      serverRef.ws.send({ type: "full-reload" })
    }
    return changed
  }

  return {
    name: "bng-auto-export::" + srcDir,
    buildStart() {
      generate()
    },
    configureServer(server) {
      serverRef = server
      server.watcher.add(srcPath)
      const router = ensureWatcherRouter(server)
      router.subscribe((event, file) => {
        if (!file || !file.startsWith(srcPathPosix) || file === toPosix(outFilePath)) return
        regenerate(event === "unlink" || event === "add")
      })
    },
    handleHotUpdate(ctx) {
      const file = toPosix(ctx.file || "")
      if (file.startsWith(srcPathPosix) && file !== toPosix(outFilePath)) {
        regenerate()
      }
    },
  }
}

/**
 * Directory-based plugin to automatically export components, directives, etc (without demos).
 * Note: If file replacement succeeds, the directory name will be replaced with the name from the file name.
 * @param {string} name - Name of the exported module
 * @param {string} srcDir - Source directory to scan directories in
 * @param {RegExp} dirPattern - Pattern to match for validation and replacement
 * @param {string|function} dirReplace - Replacement for the directory name
 * @param {RegExp} filePattern - Pattern to match for validation and replacement
 * @param {string|function} fileReplace - Replacement for the file name
 * @returns {object} - Plugin thing
 */
export function autoExportDirs(name, srcDir, dirPattern, dirReplace, filePattern, fileReplace) {
  const srcPath = path.resolve(__dirname, "src", srcDir)
  const srcPathPosix = toPosix(srcPath)

  const [_, outFilePath] = getGenFilePath(name)
  let serverRef = null

  const generate = () => {
    const src = [banner]
    const names = []

    // sources
    fs.readdirSync(srcPath)
      .filter(f => fs.statSync(path.resolve(srcPath, f)).isDirectory())
      .forEach(dir => {
        fs.readdirSync(path.resolve(srcPath, dir))
          .forEach(file => {
            let name = dir
            let fname = file
            if (name.endsWith(".dev")) {
              if (isProd) return
              name = name.substring(0, name.length - 4)
            }
            if (file.includes(".dev.")) {
              if (isProd) return
              fname = fname.replace(".dev.", ".")
            }
            if (!dirPattern.test(name)) return
            if (!filePattern.test(fname)) return
            if (dirReplace) {
              name = name.replace(dirPattern, dirReplace)
            }
            if (fileReplace) {
              fname = fname.replace(filePattern, fileReplace)
              if (fname) name = fname
            }
            names.push(name)
            const spec = toRelative(path.resolve(srcPath, dir, file))
            src.push(`export { default as ${name} } from "${spec}"`)
          })
      })

    // export
    const next = src.join("\n")
    const prev = fs.existsSync(outFilePath) ? fs.readFileSync(outFilePath, "utf8") : ""
    if (next !== prev) {
      writeFile(outFilePath, next)
      return true
    }
    return false
  }

  const regenerate = (forceReload = false) => {
    const changed = generate()
    if (!serverRef) return changed
    if (changed || forceReload) {
      invalidateModuleByFile(serverRef, outFilePath)
    }
    if (forceReload) {
      serverRef.ws.send({ type: "full-reload" })
    }
    return changed
  }

  return {
    name: "bng-auto-export::" + srcDir,
    buildStart() {
      generate()
    },
    configureServer(server) {
      serverRef = server
      server.watcher.add(srcPath)
      const router = ensureWatcherRouter(server)
      router.subscribe((event, file) => {
        if (!file || !file.startsWith(srcPathPosix) || file === toPosix(outFilePath)) return
        regenerate(event === "unlink" || event === "add")
      })
    },
    handleHotUpdate(ctx) {
      const file = toPosix(ctx.file || "")
      if (file.startsWith(srcPathPosix) && file !== toPosix(outFilePath)) {
        regenerate()
      }
    },
  }
}

/**
 * Satisfies the mod compiler's imports requirement.
 **/
export function modCompilerImports() {
  const srcRoot = path.resolve(__dirname, "src")

  const [_, outFilePath] = getGenFilePath("mod-compiler-imports")

  const servicesDir = path.resolve(srcRoot, "services")
  const utilsDir = path.resolve(srcRoot, "utils")
  const bridgeIndex = path.resolve(srcRoot, "bridge/index.js")
  const servicesDirPosix = toPosix(servicesDir)
  const utilsDirPosix = toPosix(utilsDir)
  const srcRootPosix = toPosix(srcRoot)
  const bridgeIndexPosix = toPosix(bridgeIndex)
  const outFilePathPosix = toPosix(outFilePath)

  const excludedServiceDirs = [
    path.resolve(servicesDir, "modManager"),
  ]
  let serverRef = null

  function walkJsFiles(dirAbs, excludeDirAbs = []) {
    if (!fs.existsSync(dirAbs)) return []
    const res = []
    const stack = [dirAbs]
    while (stack.length) {
      const cur = stack.pop()
      if (!cur) break
      const entries = fs.readdirSync(cur)
      for (const entry of entries) {
        const abs = path.resolve(cur, entry)
        const stat = fs.statSync(abs)
        if (stat.isDirectory()) {
          if (excludeDirAbs.some(ex => abs.startsWith(ex))) continue
          stack.push(abs)
          continue
        }
        if (!stat.isFile() || !abs.endsWith(".js")) continue
        res.push(abs)
      }
    }
    return res
  }

  const isModBarrelFile = fileAbs => toPosix(fileAbs).endsWith("/index-mod.js")
  const discoverModBarrelFiles = () => walkJsFiles(srcRoot).filter(isModBarrelFile)

  function keysForFile(fileAbs) {
    const relFromSrc = toPosix(path.relative(srcRoot, fileAbs))
    return [`@/${relFromSrc}`, `/src/${relFromSrc}`]
  }

  const generate = () => {
    const modules = []
    modules.push(bridgeIndex)
    modules.push(...walkJsFiles(servicesDir, excludedServiceDirs))
    modules.push(...walkJsFiles(utilsDir))
    modules.push(...discoverModBarrelFiles())

    const uniqueModules = Array.from(new Set(modules)).sort((a, b) => a.localeCompare(b))

    const lines = [banner]

    const imports = []
    const mapEntries = []
    uniqueModules.forEach((fileAbs, i) => {
      const id = `mdl${i}`
      const spec = toRelative(fileAbs)
      imports.push(`import * as ${id} from "${spec}"`)
      for (const key of keysForFile(fileAbs)) {
        mapEntries.push(`  "${key}": () => Promise.resolve(${id}),`)
      }
    })

    lines.push(...imports, "", "export const bundledImporters = {", ...mapEntries, "}", "")

    const next = lines.join("\n")
    const prev = fs.existsSync(outFilePath) ? fs.readFileSync(outFilePath, "utf8") : ""
    if (prev !== next) {
      writeFile(outFilePath, next)
      return true
    }
    return false
  }

  const regenerate = (forceReload = false) => {
    const changed = generate()
    if (!serverRef) return changed
    if (changed || forceReload) {
      invalidateModuleByFile(serverRef, outFilePath)
    }
    if (forceReload) {
      serverRef.ws.send({ type: "full-reload" })
    }
    return changed
  }

  return {
    name: "bng-mod-compiler-imports",
    buildStart() {
      generate()
    },
    configureServer(server) {
      serverRef = server
      server.watcher.add([servicesDir, utilsDir, srcRoot, bridgeIndex])
      const router = ensureWatcherRouter(server)
      router.subscribe((event, file) => {
        if (!file || file === outFilePathPosix) return
        if (
          file.startsWith(servicesDirPosix) ||
          file.startsWith(utilsDirPosix) ||
          file === bridgeIndexPosix ||
          (file.startsWith(srcRootPosix) && isModBarrelFile(file))
        ) {
          regenerate(event === "unlink" || event === "add")
        }
      })
    },
    handleHotUpdate(ctx) {
      const file = toPosix(ctx.file || "")
      if (!file || file === outFilePathPosix) return
      if (
        file.startsWith(servicesDirPosix) ||
        file.startsWith(utilsDirPosix) ||
        file === bridgeIndexPosix ||
        (file.startsWith(srcRootPosix) && isModBarrelFile(file))
      ) {
        regenerate()
      }
    },
  }
}
